<?php
require __DIR__ . '/_guard.php';
chatweb_admin_require_permission($conn, 'users.view');
$users = mysqli_query($conn, "SELECT id, full_name, email, phone_number, account_status, block_reason, suspension_reason, created_at FROM users WHERE COALESCE(account_status,'ACTIVE') IN ('BLOCKED','SUSPENDED','DEACTIVATED') ORDER BY id DESC");
?>
<!DOCTYPE html><html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width, initial-scale=1.0"><title>Block List | Chat Web Admin</title><style>body{margin:0;background:#f7f7f8;font-family:Arial,sans-serif;color:#172033}.main{padding:30px}.panel{background:#fff;border-radius:10px;padding:22px;box-shadow:0 13px 30px rgba(15,23,42,.05);overflow:auto}a{color:#e6a300;text-decoration:none;font-weight:800}table{width:100%;border-collapse:collapse;min-width:860px}th{background:#f0f0f1}th,td{text-align:left;padding:14px;border-bottom:1px solid #e5e7eb}</style></head><body><main class="main"><a href="index.php">Dashboard</a><h1>Block List</h1><section class="panel"><table><thead><tr><th>User</th><th>Phone</th><th>Status</th><th>Reason</th><th></th></tr></thead><tbody><?php while($row=mysqli_fetch_assoc($users)){ ?><tr><td><?php echo htmlspecialchars($row['full_name'] ?: 'User'); ?><br><small><?php echo htmlspecialchars($row['email'] ?: '-'); ?></small></td><td><?php echo htmlspecialchars($row['phone_number'] ?: '-'); ?></td><td><?php echo htmlspecialchars($row['account_status']); ?></td><td><?php echo htmlspecialchars($row['block_reason'] ?: $row['suspension_reason'] ?: '-'); ?></td><td><a href="user.php?id=<?php echo (int)$row['id']; ?>">View</a></td></tr><?php } ?></tbody></table></section></main></body></html>
